// Decide whether n8n is healthy, and whether this check should raise an alert.
// State is remembered between runs so a multi-day outage does not send one email
// every 15 minutes. Re-alerts every 6 hours while still down, and sends one
// "recovered" email when it comes back.
const RENOTIFY_HOURS = 6;
const item = $input.first().json;
const code = item.statusCode;
const status = (item.body && item.body.status) || null;
const healthy = code === 200 && status === 'ok';

const store = $getWorkflowStaticData('global');
const now = Date.now();
const wasDown = store.down === true;
const lastAlert = store.lastAlertAt || 0;
const hoursSince = (now - lastAlert) / 3600000;

let alert = false, subject = '', reason = '';

if (!healthy) {
  reason = code ? `readiness returned ${code} (${status || 'no status'})` : 'no response from n8n';
  if (!wasDown) { alert = true; subject = 'n8n is DOWN — Content Engine'; }
  else if (hoursSince >= RENOTIFY_HOURS) { alert = true; subject = `n8n still DOWN (${Math.floor(hoursSince)}h) — Content Engine`; }
  store.down = true;
  if (alert) store.lastAlertAt = now;
} else {
  if (wasDown) { alert = true; subject = 'n8n RECOVERED — Content Engine'; reason = 'readiness is returning 200 again'; }
  store.down = false;
  store.lastAlertAt = 0;
}

const body = [
  subject,
  '',
  `Checked: ${'https://YOUR_N8N_HOST/healthz/readiness'}`,
  `Result: ${reason}`,
  `Time: ${new Date(now).toISOString()}`,
  '',
  healthy ? 'No action needed.' : 'Fix: open Railway, n8n service, and Redeploy. Nothing is lost — workflows and data live in separate services.',
].join('\n');

return [{ json: { alert, healthy, subject, body, reason } }];
